mapper.select:

left join inbound_order io on iod.inbound_order_id = io.inbound_order_id

    iod.material_id = #{materialId}

        and date(iod.inbound_time) >= #{startDate}


        and date(iod.inbound_time) <= #{endDate}


order by iod.inbound_time desc

select
    sum(iod.quantity) as total_quantity,
    count(distinct iod.inbound_order_id) as order_count
from inbound_order_detail iod
left join inbound_order io on iod.inbound_order_id = io.inbound_order_id

    iod.material_id = #{materialId}
    and io.inbound_status = 'completed'

        and io.warehouse_id = #{warehouseId}


        and date(iod.inbound_time) >= #{startDate}


        and date(iod.inbound_time) <= #{endDate}

select iod.detail_id, iod.material_id, iod.material_batch_id, iod.quantity, iod.expiry_date, iod.qr_code, io.warehouse_id, w.warehouse_name, datediff(iod.expiry_date, curdate()) as days_until_expiry from inbound_order_detail iod left join inbound_order io on iod.inbound_order_id = io.inbound_order_id left join inv_warehouse w on io.warehouse_id = w.warehouse_id and w.del_flag = '0'
io.inbound_status = 'completed' and iod.expiry_date is not null and datediff(iod.expiry_date, curdate()) between 0 and #{days}
and io.warehouse_id = #{warehouseId}
order by iod.expiry_date
